Here's a React custom hook for tracking window resize:

```javascript
import { useState, useEffect } from 'react';

function useWindowSize() {
    const [windowSize, setWindowSize] = useState({
        width: window.innerWidth,
        height: window.innerHeight,
    });

    useEffect(() => {
        let timeoutId = null;

        const handleResize = () => {
            if (timeoutId) cancelAnimationFrame(timeoutId);
            timeoutId = requestAnimationFrame(() => {
                setWindowSize({
                    width: window.innerWidth,
                    height: window.innerHeight,
                });
            });
        };

        window.addEventListener('resize', handleResize, { passive: true });
        return () => {
            if (timeoutId) cancelAnimationFrame(timeoutId);
            window.removeEventListener('resize', handleResize);
        };
    }, []);

    return windowSize;
}

export default useWindowSize;

// Usage:
function ResponsiveComponent() {
    const { width, height } = useWindowSize();
    return (
        <div>
            <p>Window: {width}x{height}</p>
            {width < 768 ? <MobileView /> : <DesktopView />}
        </div>
    );
}
```

This hook uses requestAnimationFrame for smooth performance. The { passive: true } option improves scrolling performance. Cleanup removes the event listener on unmount.
